parts.script:
// State: { listReceived, list, currentPart, tickOfLastSend }
if (!ctx.state.listReceived) {
  // Look for Node 2's response to our 'list' request — response flows back automatically
  // one tick after Node 2 processes it, on this same connector (no reverse connector needed).
  const resp = ctx.responses.find((r) => r.value && r.value.type === 'list');
  if (resp) {
    const list = resp.value.parts;
    ctx.log(`Received list of ${list.length} BusinessCapability part(s) from "${resp.fromLabel}".`);
    const first = list.length ? list[Math.floor(Math.random() * list.length)] : null;
    if (first) ctx.log(`Sending first random part: "${first.label}".`);
    return {
      value: first,
      state: { listReceived: true, list, currentPart: first, tickOfLastSend: ctx.tick },
      leftBadge: { text: first ? first.label : 'no capabilities found', color: '#2f8f4e' },
    };
  }
  ctx.log("Requesting capability list ('list')...");
  return { value: 'list', state: ctx.state, leftBadge: { text: 'list', color: '#2f8f4e' } };
}

// Already have the list. Every 20 ticks, rotate to a new random part.
if (ctx.tick - ctx.state.tickOfLastSend >= 20) {
  const list = ctx.state.list;
  const next = list.length ? list[Math.floor(Math.random() * list.length)] : null;
  ctx.log(`20 ticks elapsed — sending new random part: "${next?.label}".`);
  return { value: next, state: { ...ctx.state, currentPart: next, tickOfLastSend: ctx.tick }, leftBadge: { text: next ? next.label : 'no capabilities found', color: '#2f8f4e' } };
}

// Between rotations: keep outputting the same part (downstream ignores repeats).
return { value: ctx.state.currentPart, state: ctx.state, leftBadge: { text: ctx.state.currentPart ? ctx.state.currentPart.label : 'no capabilities found', color: '#2f8f4e' } };

// Uses a case statement (switch) to decide what to do with the incoming request.
const request = ctx.inputs[0]?.value;
switch (request) {
  case 'list': {
    const caps = ctx.findParts({ type: 'BusinessCapability', model: ctx.part.model })
      .map((p) => ({ id: p.id, label: p.label }));
    ctx.log(`Got 'list' request — responding with ${caps.length} BusinessCapability part(s).`);
    return { value: 'listed', response: { type: 'list', parts: caps }, leftBadge: { text: 'listed', color: '#2f8f4e' } };
  }
  default:
    // Nothing to act on — already responded, or Node 1 has moved on to forwarding parts.
    return { value: null };
}

const incoming = ctx.inputs[0]?.value;
// Requester broadcasts ONE value to every outgoing connector, so Relay also sees its
// 'list' request string during the request phase — must check this is actually a
// Part-shaped object (not just truthy) before treating it as something to forward.
const isPart = incoming && typeof incoming === 'object' && !!incoming.id;
const isNewPart = isPart && (!ctx.state.lastPart || ctx.state.lastPart.id !== incoming.id);

if (isNewPart) {
  ctx.log(`Received new part "${incoming.label}" at tick ${ctx.tick} — forwarding to Node 4.`);
  return { value: incoming, state: { lastPart: incoming, receivedTick: ctx.tick }, leftBadge: { text: incoming.label, color: '#2f8f4e' } };
}

// Nothing new — hold the last part rather than re-triggering Node 4's own "new value" check.
return { value: ctx.state.lastPart ?? null, state: ctx.state, leftBadge: { text: ctx.state.lastPart ? ctx.state.lastPart.label : 'nothing yet', color: '#2f8f4e' } };

const part = ctx.inputs[0]?.value;
if (part && part.label !== ctx.state.lastLabel) {
  ctx.log(`Message box: received part "${part.label}" (tick ${ctx.tick}).`);
  return { value: part.label, state: { lastLabel: part.label }, leftBadge: { text: part.label, color: '#2f8f4e' } };
}
return { value: ctx.state.lastLabel ?? null, state: ctx.state, leftBadge: { text: ctx.state.lastLabel ?? 'nothing yet', color: '#2f8f4e' } };
